<script setup lang="ts">
import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{vendorAdminAPI,getApiErrorMessage}from'../../services/api';import type{Vendor}from'../../services/api';import StatusBadge from'../../components/StatusBadge.vue';import ReasonDialog from'../../components/ReasonDialog.vue';
const route=useRoute(),vendor=ref<Vendor|null>(null),loading=ref(true),saving=ref(false),error=ref(''),message=ref(''),reasonOpen=ref(false),form=ref({business_name:'',contact_name:'',phone:''});async function load(){loading.value=true;try{vendor.value=await vendorAdminAPI.getVendor(Number(route.params.id));form.value={business_name:vendor.value.business_name,contact_name:vendor.value.contact_name||'',phone:vendor.value.phone||''}}catch(e:unknown){error.value=getApiErrorMessage(e,'Vendor could not be loaded.')}finally{loading.value=false}}async function save(){saving.value=true;error.value='';try{vendor.value=await vendorAdminAPI.updateVendor(vendor.value!.id,{...form.value});message.value='Vendor updated.'}catch(e:unknown){error.value=getApiErrorMessage(e,'Vendor could not be updated.')}finally{saving.value=false}}async function suspend(reason:string){saving.value=true;try{vendor.value=await vendorAdminAPI.updateVendorStatus(vendor.value!.id,'suspended',reason);reasonOpen.value=false;message.value='Vendor suspended.'}catch(e:unknown){error.value=getApiErrorMessage(e,'Vendor could not be suspended.')}finally{saving.value=false}}async function reactivate(){saving.value=true;try{vendor.value=await vendorAdminAPI.updateVendorStatus(vendor.value!.id,'active');message.value='Vendor reactivated.'}catch(e:unknown){error.value=getApiErrorMessage(e,'Vendor could not be reactivated.')}finally{saving.value=false}}async function invite(){saving.value=true;try{const r=await vendorAdminAPI.resendInvite(vendor.value!.id);message.value=r.message||'Invite resent.'}catch(e:unknown){error.value=getApiErrorMessage(e,'Invite could not be sent.')}finally{saving.value=false}}onMounted(load)
</script><template><main class="admin-detail"><router-link to="/admin/vendors">&larr; Back to vendors</router-link><div v-if="loading" class="state">Loading vendor...</div><template v-else-if="vendor"><header><div><p>VENDOR {{vendor.code}}</p><h1>{{vendor.business_name}}</h1></div><StatusBadge :status="vendor.status"/></header><div v-if="message" class="success">{{message}}</div><div v-if="error" class="error">{{error}}</div><section class="card"><div class="code"><strong>{{vendor.code}}</strong><span>{{vendor.email}}</span></div><form @submit.prevent="save"><label>Business name<input v-model="form.business_name" required/></label><label>Contact name<input v-model="form.contact_name"/></label><label>Phone<input v-model="form.phone"/></label><button :disabled="saving">{{saving?'Saving...':'Save details'}}</button></form><div class="actions"><button :disabled="saving" @click="invite">Resend invite</button><button v-if="vendor.status==='active'" class="danger" :disabled="saving" @click="reasonOpen=true">Suspend</button><button v-else :disabled="saving" @click="reactivate">Reactivate</button></div></section><ReasonDialog :open="reasonOpen" title="Suspend this vendor?" confirm-text="Suspend vendor" @close="reasonOpen=false" @confirm="suspend"><p class="warning">All of this vendor's products will be hidden from the website and they will be signed out.</p></ReasonDialog></template></main></template><style scoped>.admin-detail{padding:18px 28px}.admin-detail>a{display:inline-block;margin:0 0 14px;color:#075397;text-decoration:none}.admin-detail header{display:flex;justify-content:space-between;align-items:center}.admin-detail header p{margin:0;color:#075397;font-size:.66rem;font-weight:800}.admin-detail h1{margin:4px 0 16px}.card{padding:20px;border:1px solid #e6ebf1;border-radius:8px;background:#fff}.code{display:flex;align-items:center;gap:12px;margin-bottom:14px}.code strong{padding:8px 12px;border-radius:999px;background:#075397;color:#fff}.code span{color:#64748b}.card form{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.card label{display:flex;flex-direction:column;gap:6px;font-size:.78rem;font-weight:750}.card input{height:42px;padding:0 10px;border:1px solid #cbd5e1;border-radius:6px}.card form button{grid-column:3;height:42px;border:0;border-radius:6px;background:#ff7900;color:#fff;font-weight:800}.actions{display:flex;gap:8px;margin-top:16px}.actions button{height:40px;padding:0 12px;border:1px solid #dbe3ec;border-radius:6px;background:#fff;font-weight:750}.actions .danger{border-color:#b42318;color:#b42318}.warning{margin:8px 0;color:#526579}.success,.error,.state{padding:10px;border-radius:6px;margin-bottom:10px}.success{background:#e8f7ef;color:#18794e}.error{background:#feeaea;color:#b42318}@media(max-width:760px){.admin-detail{padding:14px}.card form{grid-template-columns:1fr}.card form button{grid-column:1}}</style>